CREATE TYPE "DeskApprovalStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');

-- CreateEnum
CREATE TYPE "EmployeeSyncMode" AS ENUM ('DRY', 'LIVE');

-- CreateEnum
CREATE TYPE "EmployeeSyncStatus" AS ENUM ('OK', 'REJECTED');

