-- --- Hand-written: what Prisma's schema language cannot express ------------

-- At most one PENDING request per (desk, user, date); decided requests are
-- history and may repeat (decision 0326). No `map:` and no Prisma index, so
-- `prisma migrate diff` does not know about it — do not let a generated
-- migration drop it.
CREATE UNIQUE INDEX "DeskApprovalRequest_pending_key"
  ON "DeskApprovalRequest" ("deskId", "userId", "date")
  WHERE "status" = 'PENDING';

-- The contract's `#RRGGBB`, stated in the database too, so it cannot hold a
-- colour the API would refuse.
ALTER TABLE "Hive"
  ADD CONSTRAINT "Hive_color_check" CHECK ("color" ~ '^#[0-9A-Fa-f]{6}$');

-- Singleton, the same way the window and limit settings are one: the primary
-- key forbids a second row with id 1, the CHECK forbids every other id.
ALTER TABLE "EmployeeSyncSettings"
  ADD CONSTRAINT "EmployeeSyncSettings_singleton_check" CHECK ("id" = 1);

-- The table must never be empty, like its neighbours: dry run until an admin
-- switches live mode on (decision 0330). `updatedAt` has no default.
INSERT INTO "EmployeeSyncSettings" ("id", "liveMode", "updatedAt")
VALUES (1, false, NOW())
ON CONFLICT ("id") DO NOTHING;
